// 시트의 Death Save 굴림 → 그 캐릭터 토큰(현재 플레이어 페이지 우선)에 기록
// v2.9.2: 2024 시트의 [Stabilize] 버튼 → 시트 값(hitpoints.deathSaves.open)이 꺼지면 Mod도 안정화로 (채팅엔 아무것도 안 올라와서 시트 값을 봐요)
const sheetStab = () => { try { for (const id of Object.keys(S.death || {})) { const st = S.death[id]; if (!st || st.dead || st.stable) continue;
    const tok = getObj('graphic', id), ch = tok && getObj('character', tok.get('represents')); if (!ch) continue;
    const a = findObjs({ type: 'attribute', characterid: ch.id, name: 'store' })[0]; if (!a) continue;
    let v = a.get('current'); if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { continue; } }
    const hp = v && v.hitpoints, ds = hp && hp.deathSaves; if (!ds || ds.open !== false || (+hp.currentHP || 0) > 0) continue;
    if (!st.sheetOpen) continue;   // 쓰러진 뒤 시트 창이 한 번 열린 걸 본 다음에만 (처음부터 닫혀 있던 값은 무시)
    st.stable = true; setMarker(tok, 'sleepy', true); dsMarkers(tok, st);
    sendFor(tok, deathCard(tok, st, '시트에서 안정화', false, 'dsh')); if (typeof queueBoard === 'function') queueBoard(); } } catch (e) { log(SCRIPT + ' sheetStab: ' + e); } };
const sheetOpenSeen = () => { try { for (const id of Object.keys(S.death || {})) { const st = S.death[id]; if (!st || st.sheetOpen || st.dead || st.stable) continue;
    const tok = getObj('graphic', id), ch = tok && getObj('character', tok.get('represents')); if (!ch) continue;
    const a = findObjs({ type: 'attribute', characterid: ch.id, name: 'store' })[0]; if (!a) continue;
    let v = a.get('current'); if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { continue; } }
    const ds = v && v.hitpoints && v.hitpoints.deathSaves; if (ds && ds.open === true) st.sheetOpen = true; } } catch (e) {} };
setInterval(() => { sheetOpenSeen(); sheetStab(); }, 3000);
on('change:attribute', a => { try { if (a.get('name') === 'store' && Object.keys(S.death || {}).length) { sheetOpenSeen(); sheetStab(); } } catch (e) {} });
